exemplarCssAdditions.css:
.orb{width:230px;height:230px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#fef3c7,#fbbf24 70%,#d97706);box-shadow:0 0 60px rgba(251,191,36,.55),inset 0 -12px 20px rgba(180,83,9,.25),0 12px 28px rgba(0,0,0,.18);display:flex;align-items:center;justify-content:center}
/* PREMIUM gold-foil disc: */
.orb--foil{background:conic-gradient(from 210deg,#7a5c1e,#f4e0a0 45%,#9c7c33 70%,#7a5c1e);box-shadow:0 16px 40px rgba(0,0,0,.4),inset 0 1px 0 rgba(255,255,255,.18)}

.wordmark{font-family:Fraunces,serif;font-weight:800;font-size:118px;line-height:.92;letter-spacing:-.03em;background:linear-gradient(96deg,var(--brand-1),var(--brand-2) 55%,var(--accent));background-size:300% 100%;-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent;animation:vos-sheen 8s linear infinite;will-change:background-position}
@keyframes vos-sheen{from{background-position:0% 50%}to{background-position:300% 50%}}
/* PREMIUM engraved gold-foil (static or 16s): */
.wordmark--foil{background:linear-gradient(180deg,#8a6d2f,#f6e6a8 45%,#9c7c33);-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-fill-color:transparent;text-shadow:0 1px 0 rgba(0,0,0,.25)}

@keyframes vos-breathe{0%,100%{transform:scale(1)}50%{transform:scale(1.025)}}
@keyframes vos-bounceNum{0%,100%{transform:scale(1) rotate(-3deg)}50%{transform:scale(1.06) rotate(3deg)}}
@keyframes vos-twinkle{0%,100%{opacity:.25;transform:scale(.8)}50%{opacity:1;transform:scale(1.2)}}
@keyframes vos-float{0%,100%{transform:translateY(0)}50%{transform:translateY(-10px)}}
@keyframes vos-spin{to{transform:rotate(360deg)}}
/* PREMIUM: same names, longer durations + tiny amplitude e.g. vos-breathe at 12s with scale(1.012) */
